parameters.jsCode:
const response = $input.first().json;

const text = response.content?.parts
  ?.map(part => part.text || '')
  .join('');

if (!text) {
  throw new Error('Gemini returned an empty response.');
}

let parsed;

try {
  parsed = JSON.parse(text);
} catch {
  throw new Error('Gemini returned invalid JSON.');
}

if (!Array.isArray(parsed.questions)) {
  throw new Error('Gemini response must contain a questions array.');
}

const allowedCategories = [
  'functional',
  'non_functional',
  'security',
  'usability',
  'performance',
  'stakeholder',
  'constraint'
];

const allowedPriorities = ['high', 'medium', 'low'];

if (parsed.questions.length < 5 || parsed.questions.length > 7) {
  throw new Error('Gemini must generate between 5 and 7 questions.');
}

const questions = parsed.questions.map((item, index) => {
  if (
    typeof item.question !== 'string' ||
    !item.question.trim() ||
    !allowedCategories.includes(item.category) ||
    !allowedPriorities.includes(item.priority)
  ) {
    throw new Error(`Invalid question structure at index ${index}.`);
  }

  return {
    question: item.question.trim(),
    category: item.category,
    priority: item.priority
  };
});

return [
  {
    json: {
      project_id: $('Get Project Details').first().json.id,
      questions,
      question_count: questions.length
    }
  }
];

